const char *KIMM_CAR_linear_model_frame()
{
  return "model linearized_model \"KIMM_CAR\" \n  parameter Integer n = 38 \"number of states\";\n  parameter Integer m = 0 \"number of inputs\";\n  parameter Integer p = 0 \"number of outputs\";\n"
  "  parameter Real x0[n] = %s;\n"
  "  parameter Real u0[m] = %s;\n"
  "\n"
  "  parameter Real A[n, n] =\n\t[%s];\n\n"
  "  parameter Real B[n, m] = zeros(n, m);%s\n\n"
  "  parameter Real C[p, n] = zeros(p, n);%s\n\n"
  "  parameter Real D[p, m] = zeros(p, m);%s\n\n"
  "\n"
  "  Real x[n](start=x0);\n"
  "  input Real u[m];\n"
  "  output Real y[p];\n"
  "\n"
  "  Real 'x_ackerman_Steering_Model.d_theta' = x[1];\n""  Real 'x_ackerman_Steering_Model.theta' = x[2];\n""  Real 'x_body_Model.d_pitch' = x[3];\n""  Real 'x_body_Model.d_roll' = x[4];\n""  Real 'x_body_Model.d_yaw' = x[5];\n""  Real 'x_body_Model.dx' = x[6];\n""  Real 'x_body_Model.dy' = x[7];\n""  Real 'x_body_Model.dz' = x[8];\n""  Real 'x_body_Model.pitch' = x[9];\n""  Real 'x_body_Model.roll' = x[10];\n""  Real 'x_body_Model.x' = x[11];\n""  Real 'x_body_Model.y' = x[12];\n""  Real 'x_body_Model.yaw' = x[13];\n""  Real 'x_body_Model.z' = x[14];\n""  Real 'x_suspension_front_left.tire_z_pos' = x[15];\n""  Real 'x_suspension_front_right.tire_z_pos' = x[16];\n""  Real 'x_suspension_rear_left.tire_z_pos' = x[17];\n""  Real 'x_suspension_rear_right.tire_z_pos' = x[18];\n""  Real 'x_tire_front_left.brake' = x[19];\n""  Real 'x_tire_front_left.d_brake' = x[20];\n""  Real 'x_tire_front_left.d_roll' = x[21];\n""  Real 'x_tire_front_left.dz' = x[22];\n""  Real 'x_tire_front_left.roll' = x[23];\n""  Real 'x_tire_front_right.brake' = x[24];\n""  Real 'x_tire_front_right.d_brake' = x[25];\n""  Real 'x_tire_front_right.d_roll' = x[26];\n""  Real 'x_tire_front_right.dz' = x[27];\n""  Real 'x_tire_front_right.roll' = x[28];\n""  Real 'x_tire_rear_left.brake' = x[29];\n""  Real 'x_tire_rear_left.d_brake' = x[30];\n""  Real 'x_tire_rear_left.d_roll' = x[31];\n""  Real 'x_tire_rear_left.dz' = x[32];\n""  Real 'x_tire_rear_left.roll' = x[33];\n""  Real 'x_tire_rear_right.brake' = x[34];\n""  Real 'x_tire_rear_right.d_brake' = x[35];\n""  Real 'x_tire_rear_right.d_roll' = x[36];\n""  Real 'x_tire_rear_right.dz' = x[37];\n""  Real 'x_tire_rear_right.roll' = x[38];\n"
  "equation\n  der(x) = A * x + B * u;\n  y = C * x + D * u;\nend linearized_model;\n";
}
